for field,name in [(0x39,'Game.IsSSUniformMode'),(0x3a,'Game.SSUniformCamouflage'),(0x3b,'Game.bSSUniformCamouflageBlown'),(0x3c,'Game.PlayerRoot')]:
 pat=re.compile(rb'([\x40\x41])'+struct.pack('<III',0,0x15,field)+b'\xff'*4)
 rows=[]
 for f in funcs:
  c=b[f['code_offset']:f['code_offset']+f['length']]
  hits=list(pat.finditer(c))
  if hits:rows.append({'function':f['name'],'code_offset':hex(f['code_offset']),'refs':[{'offset':hex(f['code_offset']+h.start()),'access':'reference' if h[1]==b'\x40' else 'read','next':c[h.end():h.end()+24].hex()} for h in hits]})
 print(json.dumps({'field':name,'references':rows}))
for f in funcs:
 if f['name'] in [' NPCState::GetCamouflageBlown',' NPCState::SetCamouflageBlown',' NPCState::GetSpottedCamouflaged',' NPCState::SetSpottedCamouflaged',' Nazi::IsCamouflaged',' Decoy::IsCamouflaged',' ConditionedSSUniformAction::Execute',' Third_Person_Camera::IsCamouflaged']:
  print(json.dumps({**f,'code_offset':hex(f['code_offset']),'code':b[f['code_offset']:f['code_offset']+f['length']].hex()}))
for f in funcs:
 if re.search(r'Third_Person_Camera::.*(NonInteractive|Finish|Uniform|OnAnim|Callback)|Nazi::.*(Visib|Vision|See|Spot|Can|CheckEnemy|Hostil|Team)',f['name']):
  print(json.dumps({**f,'code_offset':hex(f['code_offset'])}))
`;
