const base=load("mirBase");
const extra=String.raw`
funcs=[f for f in funcs if not any(g['code_offset']>f['code_offset'] and g['code_offset']+g['length']<=f['code_offset']+f['length'] for g in funcs)]
for f in funcs:
 if f['name'].startswith('cc_') or re.search(r'(NonInteractive|AnimationMarker|FinishAnim|CompleteAnim|Script|Console)',f['name']) and ('Third_Person_Camera::' in f['name'] or f['name'].startswith('cc_')):
  print(json.dumps({**f,'code_offset':hex(f['code_offset'])}))
for f in funcs:
 if f['name']==' Third_Person_Camera::OnAnimationMarkerEx':
  print(json.dumps({**f,'code_offset':hex(f['code_offset']),'code':b[f['code_offset']:f['code_offset']+f['length']].hex()}))
for start,end in [(0x26ff00,0x270427),(0x25e200,0x25f500),(0x2bea10,0x2bead0)]:
 for m in re.finditer(rb'[\x20-\x7e]{4,}|(?:[\x20-\x7e]\x00){4,}',b[start:end]):
  v=m[0].decode('utf-16le') if b'\0' in m[0] else m[0].decode('ascii')
  print(json.dumps({'offset':hex(start+m.start()),'text':v}))
print(json.dumps({'non_containing_function_records':len(funcs)}))
`;
text(await tools.exec_command({cmd:"$vaPython = @'\n"+base+extra+"\n'@\n$vaPython | python -","sandbox_permissions":"require_escalated","justification":"May I inspect existing outfit animation callbacks and console commands read-only to determine whether a DLL is needed?","max_output_tokens":7000}));

